diff --git a/CHANGELOG.md b/CHANGELOG.md
index a9a0588..7d2c376 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -3,6 +3,7 @@
 ## Unreleased

 - Faster tag lookup.
+- `addItem` now throws an Error for invalid items and stores names, tags and units in normalized form.

 ## 1.4.2 - 2026-09-30

diff --git a/src/items.js b/src/items.js
index b1cae5b..9429952 100644
--- a/src/items.js
+++ b/src/items.js
@@ -6,10 +6,28 @@ export async function findByTag(tag) {
   return items.filter((item) => item.tags.includes(tag));
 }

-/** Adds an item with the next free id. */
+/** Adds a valid item with the next free id; throws an Error if the item is invalid. */
 export async function addItem(item) {
-  if (!item.name) throw new Error("Item needs a name.");
+  if (!item || typeof item !== "object") throw new Error("Item must be an object.");
+  if (typeof item.name !== "string" || !item.name.trim()) throw new Error("Item needs a name.");
+  if (!Number.isInteger(item.qty) || item.qty < 0) {
+    throw new Error("Item qty must be a whole number, 0 or more.");
+  }
+  const unit = item.unit ?? "";
+  if (typeof unit !== "string") throw new Error("Item unit must be a string.");
+  const rawTags = item.tags ?? [];
+  if (!Array.isArray(rawTags) || rawTags.some((t) => typeof t !== "string")) {
+    throw new Error("Item tags must be an array of strings.");
+  }
+  const tags = [...new Set(rawTags.map((t) => t.toLowerCase()))].sort();
+  if (item.expires !== undefined) {
+    const valid =
+      typeof item.expires === "string" &&
+      /^\d{4}-\d{2}-\d{2}$/.test(item.expires) &&
+      new Date(item.expires).toISOString().slice(0, 10) === item.expires;
+    if (!valid) throw new Error("Item expires must be a date written YYYY-MM-DD.");
+  }
   const items = await fetchItems();
   const id = Math.max(0, ...items.map((i) => i.id)) + 1;
-  return saveItem({ tags: [], unit: "", ...item, id });
+  return saveItem({ ...item, name: item.name.trim().toLowerCase(), unit, tags, id });
 }
